# Generated by tools/build_engine.py from Eir.ipynb, cell 18.
# Edit the notebook, not this file, then rebuild.
# The action at the end of this cell is in r18_triage.py.
# CELL 13: TRIAGE   (Eir 2.0.13)
# ============================================================================
# Rewritten. This cell used to print three raw dumps: a count of every
# coordination number, an ECoN table in which most rows read 1.0000, and a
# bare list of flagged filenames. Between them they said that something was
# unusual without saying what, why, or what to do, which produces concern
# rather than understanding.
#
# It now answers three questions instead:
#
#   1. Which sites have an unusual coordination, and WHY is each one unusual?
#      Every entry is assigned a cause, and the causes are ranked by what they
#      would mean if true. A cation half a lattice vector from its site is a
#      different problem from a Jahn-Teller elongation, and both look like a
#      low coordination number until they are separated.
#
#   2. Which structures are flagged, by WHICH screen, and what does that
#      screen see? A filename on its own cannot be acted on.
#
#   3. What is worth looking at first?
#
# Nothing here recomputes anything. It reads the columns the screens already
# wrote and arranges them so they can be acted on.

def triage(dfq, max_listed=12, verbose=True):
    """Turn the screening columns into a report that can be acted on."""
    L = []
    def out(s=""):
        L.append(s)

    if dfq is None or not len(dfq):
        print("Run the post-processing cell first.")
        return None

    n_struct, n_sites = dfq["filename"].nunique(), len(dfq)

    def num(c):
        return pd.to_numeric(dfq[c], errors="coerce") if c in dfq.columns else pd.Series(dtype=float)

    def is_false(frame, c):
        return frame[c].astype(str).str.lower().eq("false") if c in frame.columns else pd.Series(False, index=frame.index)

    cn_rel, cn_ = num("cn_relative"), num("cn")

    # Which instability index to show. Section 2 works out that a structure
    # with anti-site exchange must be read on wagii, and this cell used to go
    # on printing gii in every table underneath it: ICSD 257082 appeared at
    # 1.411 and 8352 at 1.489 on the same page that said to quote 0.919 and
    # 0.976. A report that contradicts itself is worse than one that says less,
    # so every table below now shows the recommended index and names it.
    if "gii_recommended" in dfq.columns:
        rec = dfq["gii_recommended"].astype(str)
        gii = pd.Series(np.where(rec.eq("wagii"), num("wagii"), num("gii")),
                        index=dfq.index)
        _gii_label = "gii*"
        _n_rec = int(rec.eq("wagii").sum())
    else:
        gii = num("gii")
        _gii_label = "gii"
        _n_rec = 0
    dfq = dfq.copy()
    dfq["gii_shown"] = gii
    dev = num("bvs_percent_diff").abs()

    out("=" * 78)
    out("EIR TRIAGE")
    out("=" * 78)
    # v2.0.13: the reduction to one row per structure is done ONCE, by
    # build_structure_table, which asserts that every column it takes with
    # .first() is genuinely constant within a structure and rolls up
    # any-False otherwise. drop_duplicates here was a second implementation
    # of the same reduction; it happened to read the structure_* columns and
    # so was correct, but reading the unprefixed per-site column instead
    # would have found 20 of 48 failing perovskites and missed 28.
    if 'build_structure_table' in globals():
        per = build_structure_table(dfq).set_index('filename')
    else:
        per = dfq.drop_duplicates('filename').set_index('filename')
        out('  [build_structure_table unavailable; the structure-level rows '
            'were taken from the first site of each file]')
    out(f"  {n_struct} structures, {n_sites} cation sites")
    if _n_rec:
        out(f"  {_gii_label} = the index gii_recommended names for each structure: "
            f"wagii on {per['gii_recommended'].eq('wagii').sum()} with anti-site")
        out(f"  exchange, gii on the rest. See section 3.")
    out()

    # ---------------------------------------------------------------- 0
    # The verdict first. Everything below it is the evidence for it.
    if "structure_pgrm_tier" in per.columns:
        out("-" * 78)
        out("1. INTEGRITY VERDICT")
        out("-" * 78)
        out()
        out("  Four facets, asked in order, the first failure stopping the")
        out("  assessment: can the file be READ, can the atoms be where it")
        out("  says, can we ASSESS it, is the deposited MODEL unambiguous.")
        out("  Geometry decides severity before any chemistry is read.")
        out()
        _tiers = per["structure_pgrm_tier"].value_counts()
        _mean = PGRM_TIER_MEANING
        for _k in reversed(PGRM_TIERS):
            if _k in _tiers:
                out(f"  {_k:22} {_tiers[_k]:5}  "
                    f"({100.0 * _tiers[_k] / n_struct:5.1f}%)   "
                    f"{_mean.get(_k, '')}")
        out()
        _ex = per[per["structure_pgrm_tier"] == "EXPUNGE"]
        if len(_ex):
            out("  No bond valence result should be quoted for an expunged")
            out("  structure. The number is arithmetic performed on impossible")
            out("  coordinates, and it is often a GOOD number: ICSD 85235 has")
            out("  two oxygens 2.191 A apart and a GII of 0.0047, the finest")
            out("  in the 938-structure perovskite set.")
            out()
            out("  Expunged for:")
            for _r, _n in _ex["structure_pgrm_reason"].value_counts().items():
                out(f"      {str(_r):34} {_n:4}")
            out()
            _cols = [c for c in ["icsd_code", "chemical_formula", "year",
                                 "structure_pgrm_evidence"]
                     if c in _ex.columns]
            for _line in _ex[_cols].head(max_listed).to_string(
                    index=False).splitlines():
                out("      " + _line)
            if len(_ex) > max_listed:
                out(f"      ... and {len(_ex) - max_listed} more")
            out()
            out("  This list IS the reportable-error set: the per-structure")
            out("  table filtered to EXPUNGE, each row carrying the")
            out("  measurement that condemned it.")
        out()
    # ---------------------------------------------------------------- 1
    out("-" * 78)
    out("2. UNUSUAL COORDINATION: WHAT IS CAUSING IT")
    out("-" * 78)
    out()
    out("  A coordination number well away from the family norm is a symptom,")
    out("  not a diagnosis. The same low number arises from a cation on the")
    out("  wrong site, from bonds that are genuinely absent, and from ordinary")
    out("  Jahn-Teller chemistry. Each is separated below.")
    out()
    out("  These causes read the same evidence as the PGRM G facet, per site")
    out("  rather than per structure: a proposed shift is G4, a contact below")
    out("  the floor is G1, an absent shell is G3. They cannot disagree with")
    out("  section 1, because they are one measurement read two ways.")
    out()

    common = cn_rel.value_counts()
    common = set(common[common >= 0.05 * n_sites].index)
    odd = dfq[cn_rel.notna() & ~cn_rel.isin(common)].copy()
    out(f"  Coordination numbers seen on 5% or more of sites: "
        f"{sorted(int(c) for c in common)}")
    out(f"  Sites outside that set: {len(odd)} of {n_sites} "
        f"({100.0 * len(odd) / n_sites:.1f}%)")
    out()

    if len(odd):
        causes = []
        for idx, r in odd.iterrows():
            g = pd.to_numeric(pd.Series([r.get("gii_shown")]), errors="coerce").iloc[0]
            if pd.notna(r.get("proposed_shift")):
                cause = "split coordination"
            elif str(r.get("cn_plausible")).lower() == "false":
                cause = "bonds missing"
            elif str(r.get("core_geometry_plausible")).lower() == "false" or \
                 str(r.get("bvs_geometry_plausible")).lower() == "false":
                cause = "contact too short"
            elif pd.notna(g) and g < 0.25:
                cause = "probably genuine"
            else:
                cause = "unexplained"
            causes.append(cause)
        odd["cause"] = causes

        EXPLAIN = {
            "split coordination":
                "cation about half a lattice vector from where the anions "
                "expect it; a shift is proposed, nothing is changed",
            "bonds missing":
                "coordination below anything Shannon tabulates for the ion, "
                "so the bond valence sum is incomplete",
            "contact too short":
                "a bond shorter than the ions can physically allow",
            "probably genuine":
                "low coordination but the structure is otherwise sound "
                "(Jahn-Teller, lone pair, square planar)",
            "unexplained":
                "no screen fires; worth a look by eye",
        }
        order = ["split coordination", "bonds missing", "contact too short",
                 "unexplained", "probably genuine"]
        for cause in order:
            sub = odd[odd.cause == cause]
            if not len(sub):
                continue
            g = pd.to_numeric(sub["gii_shown"], errors="coerce")
            out(f"  {cause.upper()}  -  {len(sub)} sites in "
                f"{sub['filename'].nunique()} structures, median "
                f"{_gii_label} {g.median():.3f}")
            out(f"      {EXPLAIN[cause]}")
            cols = [c for c in ["icsd_code", "chemical_formula", "element",
                                "cn", "cn_relative", "gii_shown"] if c in sub.columns]
            extra = ("proposed_shift" if cause == "split coordination"
                     else "cn_shannon_min" if cause == "bonds missing" else None)
            if extra and extra in sub.columns:
                cols = cols + [extra]
            show = sub.sort_values("gii_shown", ascending=False)[cols].head(max_listed)
            for line in show.to_string(index=False).splitlines():
                out("      " + line)
            if len(sub) > max_listed:
                out(f"      ... and {len(sub) - max_listed} more")
            out()

    # ---------------------------------------------------------------- 1b
    out("-" * 78)
    out("3. WHICH INSTABILITY INDEX TO QUOTE")
    out("-" * 78)
    out()
    wag, sav = num("wagii"), num("gii_site_averaged")
    if "has_antisite_disorder" in per.columns:
        anti = per["has_antisite_disorder"].astype(str).str.lower().eq("true")
    elif "n_antisite_species" in per.columns:
        anti = pd.to_numeric(per["n_antisite_species"], errors="coerce").fillna(0) > 0
    else:
        anti = pd.Series(False, index=per.index)
    perg = per.assign(_g=pd.to_numeric(per.get("gii"), errors="coerce"),
                      _w=pd.to_numeric(per.get("wagii"), errors="coerce"),
                      _s=pd.to_numeric(per.get("gii_site_averaged"), errors="coerce"),
                      _a=anti.values)
    n_anti = int(perg["_a"].sum())
    out(f"  Structures with anti-site exchange: {n_anti} of {n_struct}")
    out()
    out("  Eir reports one bond valence sum per SPECIES per site. Where a site")
    out("  is shared, the minority species is asked what its sum would be in a")
    out("  cavity the majority sizes; it answers with something impossible, and")
    out("  gii then weights that phantom equally with the majority it sits")
    out("  among. wagii weights by occupancy; gii_site_averaged combines the")
    out("  sums at the site before taking a deviation, so the phantom never")
    out("  exists separately.")
    out()
    if n_anti:
        a, b = perg[perg["_a"]], perg[~perg["_a"]]
        out(f"      {'':22} {'gii':>8} {'wagii':>8} {'site-avg':>9}")
        out(f"      {'with anti-site (' + str(len(a)) + ')':22} "
            f"{a._g.median():>8.3f} {a._w.median():>8.3f} {a._s.median():>9.3f}")
        out(f"      {'ordered (' + str(len(b)) + ')':22} "
            f"{b._g.median():>8.3f} {b._w.median():>8.3f} {b._s.median():>9.3f}")
        out()
        ratio = (b._g / b._w).median()
        out(f"  On the structures with no shared site gii/wagii is {ratio:.3f}.")
        out("  The two are the same quantity when every occupancy is 1.0 -")
        out("  NOT, as this line claimed until v2.0.13, whenever nothing is")
        out("  shared. WAGII weights each site by its occupancy, so a vacancy")
        out("  separates them just as a shared site does. Full occupancy gives")
        out("  gii == wagii on 869 of 871 perovskites, 355 of 355 pyrochlores")
        out("  and 335 of 338 spinels, while 1543 partially occupied spinels")
        out("  sit off the line. That is what makes the weighted form safe to")
        out("  quote throughout, and the reason to quote it more widely than")
        out("  the anti-site count alone would suggest.")
        out()
        out("  QUOTE wagii (or gii_site_averaged) for the anti-site structures.")
        out("  gii_recommended carries this per structure.")
        worst = a.assign(_r=a._g / a._w).nlargest(min(8, len(a)), "_r")
        cols = [c for c in ["icsd_code", "chemical_formula"] if c in worst.columns]
        if cols:
            out()
            out("  Where the choice matters most:")
            show = worst[cols].copy()
            show["gii"] = worst._g.round(3).values
            show["wagii"] = worst._w.round(3).values
            show["site_avg"] = worst._s.round(3).values
            for line in show.to_string(index=False).splitlines():
                out("      " + line)
    else:
        out("  No anti-site exchange found; gii, wagii and gii_site_averaged")
        out("  will agree and gii can be quoted directly. State which was used")
        out("  regardless, because on a disordered set they diverge sharply.")
    out()

    # ---------------------------------------------------------------- 2
    out("-" * 78)
    out("4. WHICH SCREEN FLAGGED WHAT")
    out("-" * 78)
    out()
    SCREENS = [
        ("radii ratio", "structure_core_geometry_plausible",
         "shortest contact against the sum of the ionic radii"),
        ("bond-valence distance", "structure_bvs_geometry_plausible",
         "shortest contact against what the ion's own parameters imply"),
        ("anion-anion packing", "anion_packing_plausible",
         "two anions closer than their electron clouds allow; the only test "
         "that does not look outward from a cation"),
        ("cation-cation packing", "cation_packing_plausible",
         "two cations closer than they can be; edge- and face-sharing "
         "polyhedra reach 2.6-3.0 A and no closer"),
        ("coordination", "structure_cn_plausible",
         "bonds missing rather than too short"),
    ]
    sets = {}
    for name, col, _ in SCREENS:
        sets[name] = set(per.index[is_false(per, col)]) if col in per.columns else set()
    if "n_sites_shift_proposed" in per.columns:
        sets["half-lattice shift"] = set(
            per.index[pd.to_numeric(per["n_sites_shift_proposed"],
                                    errors="coerce").fillna(0) > 0])
    union = set().union(*sets.values()) if sets else set()

    for name, col, what in SCREENS:
        s = sets.get(name, set())
        excl = s - set().union(*[v for k, v in sets.items() if k != name]) if s else set()
        out(f"  {name:<22} {len(s):4d} structures   {len(excl):3d} that no other "
            f"screen catches")
        out(f"      {what}")
    if "half-lattice shift" in sets:
        s = sets["half-lattice shift"]
        excl = s - set().union(*[v for k, v in sets.items() if k != "half-lattice shift"])
        out(f"  {'half-lattice shift':<22} {len(s):4d} structures   {len(excl):3d} that no "
            f"other screen catches")
        out("      cation on the wrong origin; a candidate position is proposed")
    out()
    out(f"  Flagged by at least one screen: {len(union)} of {n_struct} "
        f"({100.0 * len(union) / n_struct:.0f}%)")
    out()
    out("  A screen catching nothing exclusive is redundant with the others,")
    out("  not necessarily wrong. A screen with exclusive catches is earning")
    out("  its place and should be reported separately.")
    out()

    # ---------------------------------------------------------------- 3
    out("-" * 78)
    out("5. WHAT TO LOOK AT FIRST")
    out("-" * 78)
    out()
    prio = per.loc[sorted(union)].copy() if union else per.head(0).copy()
    if len(prio):
        prio["_gii"] = pd.to_numeric(prio.get("gii_shown"), errors="coerce")
        # v2.0.13: n_screens_failed is computed once in build_structure_table.
        # Every consumer used to rebuild it and they did not all use the same
        # screens, which is why the counts drifted between reports.
        if "n_screens_failed" in prio.columns:
            prio["_n"] = pd.to_numeric(prio["n_screens_failed"],
                                       errors="coerce").fillna(0).astype(int)
        else:
            prio["_n"] = 0
            for name, s in sets.items():
                prio["_n"] += prio.index.isin(s).astype(int)
        prio = prio.sort_values(["_n", "_gii"], ascending=[False, False])
        cols = [c for c in ["icsd_code", "chemical_formula", "year", "gii_shown"]
                if c in prio.columns]
        out(f"  Ranked by number of independent screens, then by GII. A structure")
        out(f"  failing several screens is failing for several reasons.")
        out()
        show = prio[cols].head(max_listed).copy()
        show.insert(0, "screens", prio["_n"].head(max_listed).values)
        for line in show.to_string(index=False).splitlines():
            out("      " + line)
        out()
        multi = int((prio["_n"] >= 2).sum())
        out(f"  {multi} structures fail two or more screens; {len(prio) - multi} "
            f"fail exactly one.")
    else:
        out("  Nothing flagged.")
    out()

    # repeat offenders: several entries of one composition, all flagged
    if "chemical_formula" in per.columns and union:
        grp = per.groupby("chemical_formula")
        rows = []
        for formula, g in grp:
            if len(g) < 3:
                continue
            n_bad = len(set(g.index) & union)
            if n_bad >= 2:
                rows.append((formula, n_bad, len(g)))
        if rows:
            rows.sort(key=lambda r: (-r[1] / r[2], -r[2]))
            out("  Compositions with several entries flagged. One bad structure")
            out("  is an accident; several of the same compound is a pattern,")
            out("  and often traces to one paper.")
            out()
            for formula, n_bad, n_tot in rows[:8]:
                out(f"      {str(formula)[:32]:<32} {n_bad} of {n_tot} flagged")
            out()

    out("=" * 78)
    txt = "\n".join(L)
    if verbose:
        print(txt)
    return txt
